package org.updraft.betterstatus.monitor;
public record MonitorConfig(long intervalMillis,long timeoutMillis,int failureThreshold,int recoveryThreshold,long warningPingMillis,long criticalPingMillis) { public MonitorConfig { intervalMillis=Math.max(1000,intervalMillis); timeoutMillis=Math.max(250,timeoutMillis); failureThreshold=Math.max(1,failureThreshold); recoveryThreshold=Math.max(1,recoveryThreshold); warningPingMillis=Math.max(1,warningPingMillis); criticalPingMillis=Math.max(warningPingMillis,criticalPingMillis); } public static MonitorConfig defaults(){return new MonitorConfig(5000,3000,3,2,150,300);} }